Add({
	kind = "figure",
	id = "velarok-windblade",
	title = "Velarok Windblade",
	aliases = { "Velarok", "Kalaran Windblade" },
	subtitle = "A Man Sworn to Vengeance",
	tier = "B",
	region = "searing-gorge",
	npc = { 8479 },
