Add({
	kind = "figure",
	id = "dorius-stonetender",
	title = "Dorius Stonetender",
	aliases = { "Dorius" },
	subtitle = "Archaeologist of Ironforge",
	tier = "B",
	region = "searing-gorge",
	npc = { 8284 },
	allegiance = "Kingdom of Ironforge",
	found = "The bottom of the Grimesilt Dig Site",
	pin = { x = 63.9, y = 61.0 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Look for the wounded dwarf at the bottom of the Grimesilt dig.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Dorius Stonetender led an excavation team of Ironforge into {link:searing-gorge}the Searing Gorge{/link}. His brother is Curator Thorius of the {link:hall-of-explorers}Hall of Explorers{/link}. When the {link:dark-iron-dwarves}Dark Irons{/link} came, his team was taken, and Dorius was left wounded and bleeding in the pit at {link:grimesilt-dig-site}Grimesilt{/link}. He begs any passing stranger to help him reach the gate to {link:loch-modan}Loch Modan{/link} and the road home to {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Dorius went looking for the stones called Suntara, relics that the {link:dark-iron-dwarves}Dark Irons{/link} also desired. His fate sets his grieving brother on a path of vengeance, and draws {link:ironforge}Ironforge{/link} into the secrets of {link:the-cauldron}the Cauldron{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He led an archaeology team of {link:ironforge}Ironforge{/link} into the gorge.
• He marked {link:the-cauldron}the Cauldron{/link} so that his men would not be lost there forever.
• He fought his way toward the gate of the {link:dustfire-valley}Stonewrought Pass{/link}, despite his wounds.]=],
		},
	},
	chapters = {
		{
			key = "the-singed-letter",
			title = "The Singed Letter",
			hint = "Help Dorius reach safety, and carry what he leaves behind.",
			unlock = {
				{ type = "quest", id = 3368 },
			},
			text = [=[Dorius did not reach the gate. A shot rang out as the pass came in sight, and he fell. He left behind a letter, singed at its edges, addressed to his brother. In it he wrote that the stones were real, that the {link:dark-iron-dwarves}Dark Irons{/link} held them, and that their leader, Lathoric the Black, was using their power to enslave the excavation team. The men had been taken to {link:the-cauldron}the Cauldron{/link}. Their minds were twisted to a single task: the making of something called {link:obsidion}Obsidion{/link}. Free them, he asked. When Thorius read it, he wept, and in the name of the Light he vowed that his brother's last wish would be done.]=],
		},
		{
			key = "the-altar-of-suntara",
			title = "The Altar of Suntara",
			hint = "Go down into the Slag Pit in search of Dorius's men.",
			unlock = {
				{ type = "quest", id = 3372 },
			},
			text = [=[The archaeologists were found deep in {link:the-slag-pit}the Slag Pit{/link}, still working though their bodies were failing. One of them, dying, explained that the power of the Suntara would drive them to finish their task even after death. Only the altar of Suntara could release them, and it lacked a relic that the {link:twilight-s-hammer}Twilight's Hammer{/link} kept in the hills of {link:firewatch-ridge}Firewatch Ridge{/link}. The relic was taken from the cultists and set upon the altar.]=],
		},
		{
			key = "lathoric-the-black",
			title = "Lathoric the Black",
			hint = "See what the altar of Suntara awakens.",
			unlock = {
				{ type = "quest", id = 3566 },
			},
			text = [=[It had all been a trap. Dorius had never died. When he found the Suntara stones at {link:grimesilt-dig-site}Grimesilt{/link}, the power of {red:ragnaros}Ragnaros{/red} surged through him, and the Firelord gave him a new purpose and a new name: Lathoric the Black. He had played upon his brother's grief to lure rescuers into the gorge, so that they would win back the last stone from the {link:twilight-s-hammer}Twilight's Hammer{/link} on his behalf. {link:obsidion}Obsidion{/link} was built by the Firelord's will, he boasted, to destroy the orcs of {link:blackrock-mountain}Blackrock{/link} Spire and unite him with his brethren in the fiery depths. Then he called the golem to rise. When Thorius learned the truth, his face went white. His brother had betrayed him and all of {link:ironforge}Ironforge{/link}, and Thorius feared that if so noble a {link:dwarves}dwarf{/link} could be turned so easily, no one was safe.]=],
		},
	},
	mentions = {
		{
			text = "Suntara Stones",
			unlock = {
				{ type = "quest", id = 3367 },
			},
		},
		{
			text = "Suntara Stones, the singed letter",
			unlock = {
				{ type = "quest", id = 3368 },
			},
		},
		{
			text = "Dwarven Justice",
			unlock = {
				{ type = "quest", id = 3371 },
			},
		},
		{
			text = "Release Them",
			unlock = {
				{ type = "quest", id = 3372 },
			},
		},
		{
			text = "Rise, {link:obsidion}Obsidion{/link}!",
			unlock = {
				{ type = "quest", id = 3566 },
			},
		},
	},
	bonds = {
		{ id = "curator-thorius", name = "Curator Thorius", note = "his brother" },
		{ id = "obsidion", name = "Obsidion", note = "the golem his men were made to build" },
	},
})

